using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;

namespace VaultBridge {
    internal static class Desktop050Tests {
        static int passed;static List<string> lines;
        static void Check(bool condition,string label){if(!condition)throw new Exception("FAIL: "+label);passed++;lines.Add("PASS: "+label);}
        static void Reject(Action action,string label){bool caught=false;try{action();}catch(IOException){caught=true;}Check(caught,label);}
        static Dictionary<string,object> Read(object value){return Json.Decode<Dictionary<string,object>>(Json.Encode(value));}
        static Dictionary<string,object> Call(TransferHub hub,string action,object request,string token){using(MemoryStream stream=new MemoryStream()){hub.Handle(action,Read(request),stream,token);stream.Position=0;return Wire.Read(stream);}}
        static byte[] Reply(FeedbackDraft draft,object id,object received){return Encoding.UTF8.GetBytes(Json.Encode(new{ok=true,schema=1,clientRequestId=draft.clientRequestId,id=id,receipt="VB-"+Convert.ToString(id),receivedAt=received}));}
        internal static int Run(string workspace){
            passed=0;lines=new List<string>();string root=Path.Combine(workspace,"desktop050-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
            Settings old=Json.Decode<Settings>("{\"vault\":\"synthetic-vault\",\"style\":\"night\",\"showHelp\":false,\"checkUpdatesOnStart\":false,\"scopes\":[\"notes\"],\"devices\":[{\"name\":\"synthetic\",\"token\":\"synthetic-only\"}]}");
            Check(old.themeMode=="obsidian"&&old.accentMode=="obsidian"&&old.sentDisplay=="marked"&&FeedbackClient.DefaultEndpoint==""&&typeof(Settings).GetField("feedbackEndpoint")==null,"old settings acquire safe defaults and cannot configure a public feedback server");
            ObsidianAppearance obs=ObsidianAppearance.Parse("{\"theme\":\"obsidian\",\"accentColor\":\"#a78bfa\"}",false);Settings options=new Settings{themeMode="light",accentMode="custom",customAccent="#d9ab3a",sentDisplay="hidden",showHelp=false,checkUpdatesOnStart=false};
            ObsidianAppearance resolved=DesktopPreferences.Resolve(obs,options,true);Check(!resolved.Dark&&resolved.Hex=="#d9ab3a","manual light background and custom accent are independent of Obsidian and system");options.themeMode="dark";options.accentMode="obsidian";Check(DesktopPreferences.Resolve(obs,options,false).Dark&&DesktopPreferences.Resolve(obs,options,false).Hex=="#a78bfa","manual dark background can independently follow Obsidian accent");options.themeMode="system";Check(DesktopPreferences.Resolve(obs,options,true).Dark&&!DesktopPreferences.Resolve(obs,options,false).Dark,"system background responds independently to current system mode");options.themeMode="invalid";options.accentMode="invalid";Check(DesktopPreferences.Resolve(obs,options,false).Dark&&DesktopPreferences.Sent("invalid")=="marked","unknown preference values fall back to existing automatic behavior");options.accentMode="custom";options.customAccent="not a color";Check(DesktopPreferences.Resolve(obs,options,false).Hex=="#7f6df2","invalid custom color has a readable safe fallback");
            old.themeMode="light";old.accentMode="custom";old.customAccent="#d9ab3a";old.sentDisplay="hidden";SettingsStore settings=new SettingsStore(Path.Combine(root,"settings"));settings.Save(old);Settings kept=settings.Load();Check(kept.themeMode=="light"&&kept.accentMode=="custom"&&kept.sentDisplay=="hidden"&&kept.vault==old.vault&&kept.scopes.SequenceEqual(old.scopes)&&kept.devices[0].token=="synthetic-only"&&!kept.showHelp&&!kept.checkUpdatesOnStart,"DPAPI settings round trip preserves old authorization and all independent preferences");
            string endpoint="https://example.com/wp-json/vaultbridge-feedback/v1/submit";Check(FeedbackRules.Endpoint(endpoint).Scheme=="https","feedback endpoint accepts explicit HTTPS submit route without connecting");
            foreach(string invalid in new[]{"","http://example.com/wp-json/vaultbridge-feedback/v1/submit","https://user:synthetic@example.com/wp-json/vaultbridge-feedback/v1/submit",endpoint+"?token=synthetic",endpoint+"#fragment","https://example.com:8443/wp-json/vaultbridge-feedback/v1/submit","https://example.com/elsewhere","https://example.com\\wp-json/vaultbridge-feedback/v1/submit"})Reject(()=>FeedbackRules.Endpoint(invalid),"feedback rejects missing unsafe or unrelated endpoint");
            FeedbackDraft draft=new FeedbackDraft{body="只发送手动填写的建议"};string payload=Encoding.UTF8.GetString(FeedbackRules.Payload(draft));Check(!payload.Contains("contextOptional")&&!payload.Contains("version")&&!payload.Contains("platform"),"version and platform are not sent without opt-in");draft.contextOptional=new FeedbackContext{version="0.5.0",platform="windows"};Check(Encoding.UTF8.GetString(FeedbackRules.Payload(draft)).Contains("contextOptional"),"explicit context opt-in adds only known app version and platform");draft.contextOptional=null;
            string stable=draft.clientRequestId;FeedbackRules.Payload(draft);FeedbackRules.Payload(draft);Check(draft.clientRequestId==stable,"retry serialization retains the same submission identity");FeedbackReceipt receipt=FeedbackRules.Receipt(Reply(draft,"123",1792000000000L),201,stable);Check(receipt.receipt=="VB-123"&&receipt.receivedAt>0,"complete matching persisted receipt is accepted");Check(FeedbackRules.Receipt(Reply(draft,"123",1792000000000L),200,stable).id=="123","idempotent duplicate response accepts same receipt");Reject(()=>FeedbackRules.Receipt(Reply(draft,"123",1792000000000L),200,Guid.NewGuid().ToString("N")),"receipt for another draft cannot confirm delivery");Reject(()=>FeedbackRules.Receipt(Reply(draft,123,1792000000000L),200,stable),"numeric id cannot impersonate required decimal-string receipt");Reject(()=>FeedbackRules.Receipt(Reply(draft,"123",true),200,stable),"boolean receipt timestamp cannot confirm delivery");Reject(()=>FeedbackRules.Receipt(Encoding.UTF8.GetBytes("<html>challenge</html>"),200,stable),"HTTP 200 HTML or challenge is not successful feedback");Reject(()=>FeedbackRules.Receipt(null,503,stable),"pending service failure is not reported as delivered");Reject(()=>FeedbackRules.Receipt(null,409,stable),"conflicting submission preserves an explicit failure");draft.body=new string('a',4001);Reject(()=>FeedbackRules.Payload(draft),"feedback body exceeding 4000 characters rejected before networking");draft.body="retained synthetic draft";
            FeedbackDraftStore drafts=new FeedbackDraftStore(Path.Combine(root,"drafts"));drafts.Save(draft);FeedbackDraft loaded=drafts.Load();Check(loaded.clientRequestId==stable&&loaded.body==draft.body&&loaded.receivedAt==0,"unconfigured or failed suggestion persists as unsent draft with stable identity");Check(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(root,"drafts",stable+".protected"))).Contains(draft.body),"private desktop draft is protected with current-user DPAPI");
            FeedbackDraft edited=new FeedbackDraft{body="separate synthetic suggestion"};drafts.Save(edited);FeedbackDraft original=Json.Decode<FeedbackDraft>(Encoding.UTF8.GetString(System.Security.Cryptography.ProtectedData.Unprotect(File.ReadAllBytes(Path.Combine(root,"drafts",stable+".protected")),null,System.Security.Cryptography.DataProtectionScope.CurrentUser)));Check(original.clientRequestId==stable&&original.body==draft.body&&drafts.Load().clientRequestId==edited.clientRequestId,"a new request keeps an independently recoverable original ID and payload rather than only a backup");
            string vault=Path.Combine(root,"vault"),inbox=Path.Combine(root,"inbox"),tasks=Path.Combine(root,"tasks");Directory.CreateDirectory(vault);Directory.CreateDirectory(inbox);Directory.CreateDirectory(Path.Combine(vault,"shared"));Directory.CreateDirectory(Path.Combine(vault,".obsidian"));File.WriteAllText(Path.Combine(vault,"shared","note.md"),"shared-content");File.WriteAllText(Path.Combine(vault,"private.md"),"unshared-content");File.WriteAllText(Path.Combine(vault,".obsidian","appearance.json"),"{}");Settings transfer=new Settings{vault=vault,inbox=inbox,scopes=new List<string>{"shared"}};TransferHub hub=new TransferHub(tasks,transfer,j=>{},s=>{});string owner="synthetic-owner",another="synthetic-other-owner";
            Dictionary<string,object> partial=Call(hub,"x-compare",new{mode="notes",prefix="return"},owner);Check(!(bool)partial["complete"]&&Wire.Text(partial,"vaultId")==transfer.vaultId&&!Json.Encode(partial["files"]).Contains("private.md")&&!Json.Encode(partial).Contains(".obsidian"),"partial comparison returns only authorized raw files and never claims complete vault");
            Check(Wire.Text(partial,"targetId")==TransferHub.TargetIdentity("notes",vault,"return",transfer.vaultId),"comparison identity binds actual vault root id mode and destination prefix");Check(!Directory.Exists(Path.Combine(vault,"return"))&&Directory.GetDirectories(tasks).Length==0,"read-only comparison does not create destination or transfer tasks");Reject(()=>Call(hub,"x-compare",new{mode="files",prefix=""},owner),"generic comparison cannot enumerate private PC inbox");Reject(()=>Call(hub,"x-compare",new{mode="notes",prefix="../escape"},owner),"comparison prefix cannot escape authorized vault");transfer.scopes=new List<string>{""};Dictionary<string,object> full=Call(hub,"x-compare",new{mode="notes",prefix=""},owner);Check((bool)full["complete"]&&Json.Encode(full["files"]).Contains("private.md"),"full authorized comparison can distinguish eligible missing paths");
            Reject(()=>Call(hub,"x-compare",new{mode="notes",prefix="private.md/child"},owner),"comparison rejects a destination prefix whose ancestor is an existing file");Check(Json.Encode(full["files"]).Contains(Crypto.HashFile(Path.Combine(vault,"shared","note.md"))),"note comparison hashes raw authorized bytes without remapping Markdown");
            string id=Guid.NewGuid().ToString("N"),emptyHash=Crypto.Hash(new MemoryStream());FileItem[] files={new FileItem{path="empty.bin",size=0,sha256=emptyHash}};Call(hub,"x-request",new{id=id,mode="files",prefix="folder",files=files},owner);hub.Approve(id,inbox,true);Dictionary<string,object> completed=Call(hub,"x-commit",new{id=id,file=0},owner);string targetId=Wire.Text(completed,"targetId"),saved=Wire.Text(completed,"saved");Check(TransferRules.Hash(targetId)&&Convert.ToInt64(completed["completedAt"])>0&&Wire.Text(completed,"sha256")==emptyHash,"new successful commit returns identity timestamp actual path and original content hash");Check(Wire.Text(Call(hub,"x-verify",new{id=id,file=0,targetId=targetId},owner),"result")=="same","only matching existing final PC bytes confirm same");Reject(()=>Call(hub,"x-verify",new{id=id,file=0,targetId=targetId},another),"another paired identity cannot verify an owner's completed job");Reject(()=>Call(hub,"x-verify",new{id=id,file=0,targetId=new string('0',64)},owner),"client cannot verify receipt against another target identity");
            string target=Paths.Resolve(inbox,saved);using(FileStream locked=File.Open(target,FileMode.Open,FileAccess.ReadWrite,FileShare.None))Check(Wire.Text(Call(hub,"x-verify",new{id=id,file=0,targetId=targetId},owner),"result")=="unknown","unreadable locked final file is unknown rather than missing or confirmed same");File.WriteAllText(target,"changed");Check(Wire.Text(Call(hub,"x-verify",new{id=id,file=0,targetId=targetId},owner),"result")=="changed"&&(bool)Call(hub,"x-status",new{id=id,file=0},owner)["done"],"historical success stays distinct from now-changed destination bytes");File.Move(target,target+".retained-for-missing-check");Check(Wire.Text(Call(hub,"x-verify",new{id=id,file=0,targetId=targetId},owner),"result")=="missing","retained historical receipt cannot prove a moved file still exists");string otherInbox=Path.Combine(root,"other-inbox");Directory.CreateDirectory(otherInbox);transfer.inbox=otherInbox;Reject(()=>Call(hub,"x-verify",new{id=id,file=0,targetId=targetId},owner),"changing current inbox invalidates previous target verification");transfer.inbox=inbox;string previousVault=transfer.vaultId;transfer.vaultId="different-vault-identity";Reject(()=>Call(hub,"x-verify",new{id=id,file=0,targetId=targetId},owner),"changing PC master vault identity invalidates old target verification");transfer.vaultId=previousVault;
            TransferHub restored=new TransferHub(tasks,transfer,j=>{},s=>{});Check(Wire.Text(Call(restored,"x-status",new{id=id,file=0},owner),"targetId")==targetId,"new receipt identity survives reconstructed receiver without touching file");restored.Revoke(id);Reject(()=>Call(restored,"x-verify",new{id=id,file=0,targetId=targetId},owner),"revoked approved task cannot expose a current-file verification");
            string failedId=Guid.NewGuid().ToString("N");Call(hub,"x-request",new{id=failedId,mode="files",prefix="persist-failure",files=files},owner);hub.Approve(failedId,inbox,true);string jobPath=Path.Combine(tasks,failedId,"job.json"),retainedJob=jobPath+".before-failure";File.Move(jobPath,retainedJob);Directory.CreateDirectory(jobPath);Reject(()=>Call(hub,"x-commit",new{id=failedId,file=0},owner),"completion record persistence failure does not return a successful receipt");Check(!(bool)Call(hub,"x-status",new{id=failedId,file=0},owner)["done"]&&Wire.Text(Call(hub,"x-verify",new{id=failedId,file=0},owner),"result")=="unknown","failed receipt persistence rolls back in-memory completion and cannot fabricate current proof");Directory.Move(jobPath,jobPath+".blocked-directory-retained");File.Move(retainedJob,jobPath);Dictionary<string,object> retried=Call(hub,"x-commit",new{id=failedId,file=0},owner);Check(Convert.ToInt64(retried["completedAt"])>0&&Wire.Text(Call(hub,"x-verify",new{id=failedId,file=0,targetId=Wire.Text(retried,"targetId")},owner),"result")=="same","retry after persistence recovery reuses verified final bytes and records a fresh durable receipt");
            string legacyId=Guid.NewGuid().ToString("N"),legacyFolder=Path.Combine(tasks,legacyId);Directory.CreateDirectory(legacyFolder);File.WriteAllText(Path.Combine(legacyFolder,"job.json"),Json.Encode(new{id=legacyId,owner=TransferRules.Owner(owner),mode="files",prefix="",root=inbox,state="approved",files=files,saved=new Dictionary<string,string>{{"0","legacy.bin"}}}));TransferHub legacy=new TransferHub(tasks,transfer,j=>{},s=>{});Dictionary<string,object> historical=Call(legacy,"x-verify",new{id=legacyId,file=0},owner);Check(Wire.Text(historical,"result")=="unknown"&&Wire.Text(historical,"reason")=="legacy-receipt","old done/saved records remain historical rather than fabricated current proof");Check((bool)Call(legacy,"x-status",new{id=legacyId,file=0},owner)["done"],"old transfer completion remains backward compatible after new receiver loads");
            lines.Add("Desktop 0.5 targeted checks passed: "+passed);File.WriteAllLines(Path.Combine(workspace,"desktop050-results.txt"),lines,new UTF8Encoding(false));return passed;
        }
    }
}
